# tmp + fsync + atomic rename, 5 x 20 ms retries on a Windows FileSystemException (the GuildStore.replaceFile pattern; GuildStore's own
# helper is compiled after GCfg, so this is its own copy)
M(cfg, r"""
public static void writeAtomic(byte[] b) throws java.io.IOException {
  java.nio.file.Path tmp = FILE.resolveSibling(FILE.getFileName().toString() + ".migrate.tmp");
  java.io.FileOutputStream out = new java.io.FileOutputStream(tmp.toFile());
  try {
    out.write(b);
    out.flush();
    out.getFD().sync();
  } finally { out.close(); }
  java.io.IOException last = null;
  for (int i = 0; i < 5; i++) {
    try {
      try {
        java.nio.file.Files.move(tmp, FILE, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING, java.nio.file.StandardCopyOption.ATOMIC_MOVE });
      } catch (java.nio.file.AtomicMoveNotSupportedException a) {
        java.nio.file.Files.move(tmp, FILE, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      }
      return;
    } catch (java.nio.file.NoSuchFileException e) {
      throw e;
    } catch (java.nio.file.FileSystemException e) {
      last = e;
    }
    try { Thread.sleep(20L); } catch (InterruptedException ie) { }
  }
  try { java.nio.file.Files.deleteIfExists(tmp); } catch (Throwable t) { }
  throw last;
}""")
