M(cfg, r"""
public static void migrateSkills(java.util.Properties p) {
  String cur = p.getProperty("xpSkills");
  if (cur == null || cur.trim().length() == 0) return;
  String t = cur.trim();
  if (t.equals(DEF_SKILLS)) return;
  if (!t.equals(OLD_SKILLS)) {
    String miss = missingNew(t);
    String shown = t.length() > 300 ? t.substring(0, 300) + "..." : t;
    if (miss.length() > 0) @PKG@.GuildStore.info("config.properties: xpSkills is a changed list, kept as it is (" + shown + "). It does not list " + miss + ", so that Berserker / Priest skill XP adds no guild XP - add it in Server Setup > Guilds > Skills that count, or /guildadmin set xpSkills <list>.");
    else @PKG@.GuildStore.info("config.properties: xpSkills is a changed list that already counts Fury and Divinity - kept as it is (" + shown + "). Nothing to update.");
    return;
  }
  String keep = " (the old list is kept - add Fury,Divinity in Server Setup > Guilds > Skills that count)";
  try {
    byte[] old = java.nio.file.Files.readAllBytes(FILE);
    java.util.Properties before = new java.util.Properties();
    before.load(new java.io.ByteArrayInputStream(old));
    String bv = before.getProperty("xpSkills");
    if (bv == null || !bv.trim().equals(OLD_SKILLS)) { @PKG@.GuildStore.warn("config.properties changed while it was read - xpSkills not updated" + keep); return; }
    String text = new String(old, "ISO-8859-1");
    String[] lines = text.split("\n", -1);
    StringBuilder out = new StringBuilder(text.length() + 32);
    int changed = 0;
    boolean cont = false;
    for (int i = 0; i < lines.length; i++) {
      String l = lines[i];
      String body = l.endsWith("\r") ? l.substring(0, l.length() - 1) : l;
      if (cont) cont = contLine(body);
      else if (!commentOrBlank(body)) {
        int at = skillsValueAt(body);
        if (at >= 0 && body.startsWith(OLD_SKILLS, at) && body.substring(at + OLD_SKILLS.length()).trim().length() == 0) {
          l = l.substring(0, at) + DEF_SKILLS + l.substring(at + OLD_SKILLS.length());
          changed++;
        }
        cont = contLine(body);
      }
      if (i > 0) out.append('\n');
      out.append(l);
    }
    if (changed == 0) { @PKG@.GuildStore.warn("config.properties: xpSkills is the old default but its line could not be rewritten safely" + keep); return; }
    byte[] nb = out.toString().getBytes("ISO-8859-1");
    java.util.Properties after = new java.util.Properties();
    after.load(new java.io.ByteArrayInputStream(nb));
    if (!sameExceptSkills(before, after)) { @PKG@.GuildStore.warn("config.properties: rewriting xpSkills would change more than that line - nothing written" + keep); return; }
    writeAtomic(nb);
    p.setProperty("xpSkills", DEF_SKILLS);
    @PKG@.GuildStore.info("config.properties: xpSkills was still the old default - added Fury and Divinity (Berserker / Priest skill XP now counts for guild XP). A list an admin changed is never touched.");
  } catch (Throwable x) { @PKG@.GuildStore.warn("could not add Fury and Divinity to xpSkills in " + FILE + keep + ": " + x); }
}""")
