# limit changes, (0.1.6) kick-refund-skipped)
M(gs, r"""
public static long seedLine(java.util.HashMap byName, String line) {
  if (line == null) return 0L;
  String[] v = line.split("\\|", 5);
  if (v.length < 5) return 0L;
  long amt = parseLong(v[3], -1L);
  if (amt <= 0L) return 0L;
  boolean dep = v[2].equals("deposit");
  boolean out = v[2].equals("withdraw") || v[2].equals("disband-payout") || v[2].equals("leave-refund") || v[2].equals("kick-refund");
  if (!dep && !out) return 0L;
  String k = v[1].trim().toLowerCase();
  Object o = byName.get(k);
  long[] t = null;
  if (o != null) t = (long[]) o;
  if (t == null) { t = new long[] { 0L, 0L, 0L }; byName.put(k, t); }
  if (dep) t[0] = t[0] + amt; else t[1] = t[1] + amt;
  t[2] = t[2] + 1L;
  return dep ? amt : -amt;
}""")
