# 0.1.5 (Skyy 2026-10-01, "use %"): how a disband pays amt coins out. Rows Object[]{GMember, Long share, Long net} for EVERY member in
# member (join) order; the shares sum to amt exactly. Members with a positive net (deposited - withdrawn) share the WHOLE bank by their
# part of the positive nets: share = amt x net / total (BigInteger, rounded down); a zero or negative net gets 0. Nobody positive =
# amt / members each. The coins the rounding leaves go to the biggest contributor (highest net; tie: higher rank, then earlier join).
M(gs, r"""
public static synchronized java.util.ArrayList payouts(@PKG@.Guild g, long amt) {
  java.util.ArrayList rows = new java.util.ArrayList();
  java.util.ArrayList mems = new java.util.ArrayList(g.members.values());
  int n = mems.size();
  if (n == 0) return rows;
  long a = amt < 0L ? 0L : amt;
  long[] net = new long[n];
  java.math.BigInteger tot = java.math.BigInteger.ZERO;
  int best = 0;
  for (int i = 0; i < n; i++) {
    @PKG@.GMember m = (@PKG@.GMember) mems.get(i);
    net[i] = netValue(g, m.uuid);
    if (net[i] > 0L) tot = tot.add(java.math.BigInteger.valueOf(net[i]));
    @PKG@.GMember b = (@PKG@.GMember) mems.get(best);
    if (net[i] > net[best] || (net[i] == net[best] && (m.rank > b.rank || (m.rank == b.rank && m.joined < b.joined)))) best = i;
  }
  boolean even = tot.signum() == 0;
  java.math.BigInteger ba = java.math.BigInteger.valueOf(a);
  long[] share = new long[n];
  long given = 0L;
  for (int i = 0; i < n; i++) {
    if (even) share[i] = a / (long) n;
    else if (net[i] > 0L) share[i] = ba.multiply(java.math.BigInteger.valueOf(net[i])).divide(tot).longValue();
    given = given + share[i];
  }
  share[best] = share[best] + (a - given);
  for (int i = 0; i < n; i++) rows.add(new Object[] { mems.get(i), Long.valueOf(share[i]), Long.valueOf(net[i]) });
  return rows;
}""")
