# Disband (0.1.5: the bank goes back to the members by contribution, payouts): (1) every payee's purse must be readable (coins:fn:get)
# - else refused, nothing changed; (2) the guild file is rewritten as disbanded with bank 0 BEFORE any coin moves (a failed write
# refuses the disband, nothing changed); (3) each share is paid with coins:fn:add (offline members too: SkyyCoins pays the player's
# active profile); if ANY payout fails, every share paid so far is taken back with coins:fn:take and the live file is written again
# (refused, the bank keeps its coins) - a share that cannot be taken back stays with that member, leaves the bank as a logged
# disband-payout and counts as their withdrawal (no coin created or lost); (4) the file moves to guilds/deleted/. The file on disk never
# shows more coins than exist, so a crash can never pay the same bank twice.
# 0.1.5 review: (finding 1) a crash or kill DURING the payouts loses the unpaid shares (the file already says bank 0), so the plan is
# recorded before the first coin moves - one server-log info line + one banklog.log DISBAND-PAYOUT-START line with every payee's name,
# uuid and share - and each share gets a DISBAND-PAYOUT-PAID line as it lands, then DISBAND-PAYOUT-DONE / -CANCELLED: an admin can pay
# the missing shares by hand (no automatic replay: that could pay twice). (finding 2) the rollback rewrite of the live file is tried
# 3 times; if all fail a loud WARN names the guild and its bank (memory is right, the disk still says disbanded / bank 0; the guild
# stays dirty, so flushDirty keeps retrying every 5 s).
M(gs, r"""
public static synchronized String disbandNow(@PKG@.Guild g, String actorU, String by) {
  long amt = g.bank;
  java.util.ArrayList rows = payouts(g, amt);
  if (amt > 0L && rows.size() == 0) return "-The guild bank still holds " + amt + " coins and the guild has no members to pay them to, so " + g.name + " was NOT disbanded.";
  if (amt > 0L && !coinsReady()) return "-The guild bank still holds " + amt + " coins and SkyyCoins is not available to pay them out, so " + g.name + " was NOT disbanded.";
  if (amt > 0L) {
    for (int i = 0; i < rows.size(); i++) {
      Object[] r = (Object[]) rows.get(i);
      @PKG@.GMember m = (@PKG@.GMember) r[0];
      if (((Long) r[1]).longValue() > 0L && coinsGet(m.uid) == null) return "-" + m.name + "'s purse cannot be read right now, so the guild bank cannot be paid out and " + g.name + " was NOT disbanded (nothing changed). Try again.";
    }
  }
  try {
    java.util.Properties p = propsOf(g);
    p.setProperty("bank", "0");
    p.setProperty("disbanded", String.valueOf(System.currentTimeMillis()));
    writeProps(GDIR.resolve(g.id + ".properties"), p, "SkyyGuilds guild file - DISBANDED (" + amt + " bank coins paid back to the members by contribution), kept for the record only");
  } catch (Throwable t) {
    warn("disband of " + g.id + " refused: the guild file could not be written: " + t);
    return "-The guild file could not be written, so " + g.name + " was NOT disbanded (nothing changed). Try again.";
  }
  int np = payees(rows);
  if (amt > 0L) {
    StringBuilder plan = new StringBuilder();
    for (int i = 0; i < rows.size(); i++) {
      Object[] r = (Object[]) rows.get(i);
      long sh = ((Long) r[1]).longValue();
      if (sh <= 0L) continue;
      @PKG@.GMember m = (@PKG@.GMember) r[0];
      if (plan.length() > 0) plan.append(", ");
      plan.append(m.name).append(' ').append(m.uuid).append(' ').append(sh);
    }
    String pl = plan.toString();
    info("disband of " + g.id + " '" + g.name + "' by " + by + ": the guild file now says disbanded with bank 0; paying the bank's " + amt + " coins to " + np + " member(s) in this order: " + pl + ". If no '" + g.name + " (" + g.id + ") disbanded by' line follows, the server stopped during the payout: banklog.log marks each share PAID as it lands - pay the others by hand.");
    bankNote(g, "DISBAND-PAYOUT-START by " + by + ": bank " + amt + " coins to " + np + " member(s) in this order: " + pl + ". The guild file already says disbanded with bank 0. Each share gets a DISBAND-PAYOUT-PAID line once it is in the purse. No DISBAND-PAYOUT-DONE or DISBAND-PAYOUT-CANCELLED line after this one = the server stopped mid-payout: pay the shares without a PAID line by hand (check the first one's purse, it may have landed just before the stop).");
  }
  boolean[] paid = new boolean[rows.size()];
  String failName = null;
  int done = 0;
  for (int i = 0; i < rows.size() && amt > 0L; i++) {
    Object[] r = (Object[]) rows.get(i);
    long sh = ((Long) r[1]).longValue();
    if (sh <= 0L) continue;
    @PKG@.GMember m = (@PKG@.GMember) r[0];
    if (!coinsAdd(m.uid, sh)) { failName = m.name; break; }
    paid[i] = true;
    done = done + 1;
    bankNote(g, "DISBAND-PAYOUT-PAID " + done + "/" + np + ": " + m.name + " " + m.uuid + " " + sh + " coins.");
  }
  if (failName != null) {
    long kept = 0L;
    java.util.ArrayList stuck = new java.util.ArrayList();
    for (int i = 0; i < rows.size(); i++) {
      if (!paid[i]) continue;
      Object[] r = (Object[]) rows.get(i);
      @PKG@.GMember m = (@PKG@.GMember) r[0];
      long sh = ((Long) r[1]).longValue();
      Object back = coinsTake(m.uid, sh);
      if (back instanceof Boolean && ((Boolean) back).booleanValue()) continue;
      kept = kept + sh;
      stuck.add(r);
    }
    g.bank = amt;
    for (int i = 0; i < stuck.size(); i++) {
      Object[] r = (Object[]) stuck.get(i);
      @PKG@.GMember m = (@PKG@.GMember) r[0];
      long sh = ((Long) r[1]).longValue();
      g.bank = g.bank - sh;
      netAdd(g, m.uuid, 0L, sh);
      addLog(g, m.name, "disband-payout", sh);
    }
    g.dirty = true;
    boolean saved = false;
    for (int tries = 0; tries < 3 && !saved; tries++) saved = saveGuild(g);
    if (!saved) warn("DISBAND ROLLBACK NOT ON DISK: guild " + g.id + " '" + g.name + "' holds " + g.bank + " bank coins in memory, but guilds/" + g.id + ".properties still says DISBANDED with bank 0 after 3 tries. It is retried every 5 s; if the server stops before a save works, edit that file while the server is stopped: bank=" + g.bank + " and delete its disbanded line.");
    warn("disband of " + g.id + " refused: SkyyCoins could not pay " + failName + "'s share - the shares paid before were taken back"
         + (kept > 0L ? " except " + kept + " coins (" + shareList(stuck) + ") that stay with those members and left the bank as disband-payout" : "") + "; bank now " + g.bank);
    bankNote(g, "DISBAND-PAYOUT-CANCELLED: SkyyCoins could not pay " + failName + "'s share, so every share paid before was taken back"
         + (kept > 0L ? " except " + kept + " coins (" + shareList(stuck) + ") that stay with those members, logged above as disband-payout" : "") + "; the guild is NOT disbanded and keeps " + g.bank + " coins.");
    if (kept > 0L) return "-SkyyCoins could not pay " + failName + "'s share, so " + g.name + " was NOT disbanded. " + kept + " coins already paid could not be taken back - see the bank log. Try again.";
    return "-SkyyCoins could not pay " + failName + "'s share of the guild bank, so " + g.name + " was NOT disbanded - every coin paid so far went back to the guild bank. Try again.";
  }
  long left = amt;
  String single = null;
  for (int i = 0; i < rows.size(); i++) {
    if (!paid[i]) continue;
    Object[] r = (Object[]) rows.get(i);
    @PKG@.GMember m = (@PKG@.GMember) r[0];
    long sh = ((Long) r[1]).longValue();
    left = left - sh;
    g.bank = left;
    netAdd(g, m.uuid, 0L, sh);
    addLog(g, m.name, "disband-payout", sh);
    if (sh == amt) single = m.uuid;
  }
  if (amt > 0L) bankNote(g, "DISBAND-PAYOUT-DONE: all " + np + " share(s) paid, " + amt + " coins; the guild is disbanded.");
  g.bank = 0L;
  archive(g);
  GUILDS.remove(g.id);
  if (g.id.equals(BYNAME.get(g.name.toLowerCase()))) BYNAME.remove(g.name.toLowerCase());
  java.util.HashMap shareBy = new java.util.HashMap();
  for (int i = 0; i < rows.size(); i++) {
    Object[] r = (Object[]) rows.get(i);
    shareBy.put(((@PKG@.GMember) r[0]).uuid, r[1]);
  }
  java.util.Iterator it = g.members.values().iterator();
  while (it.hasNext()) {
    @PKG@.GMember m = (@PKG@.GMember) it.next();
    BYPLAYER.remove(m.uuid);
    unpublish(m.uuid);
    if (actorU == null || !actorU.equals(m.uuid)) {
      Object so = shareBy.get(m.uuid);
      long sh = so instanceof Long ? ((Long) so).longValue() : 0L;
      sayU(m.uid, "[Guild] " + g.name + " was disbanded by " + by + "." + (sh > 0L ? " Your share of the guild bank, " + sh + " coins, is in your purse." : ""), "#ffd070");
    }
  }
  java.util.Iterator ii = INVITES.entrySet().iterator();
  while (ii.hasNext()) {
    java.util.Map.Entry e = (java.util.Map.Entry) ii.next();
    Object[] v = (Object[]) e.getValue();
    if (v != null && g.id.equals(v[0])) ii.remove();
  }
  saveIndex();
  info(g.name + " (" + g.id + ") disbanded by " + by + (amt > 0L ? ", bank " + amt + " coins paid back by contribution: " + shareList(rows) : ""));
  if (amt <= 0L) return "+" + g.name + " is disbanded.";
  if (single != null) {
    boolean self = actorU != null && actorU.equals(single);
    String who = self ? "your purse." : g.member(single).name + "'s purse.";
    return "+" + g.name + " is disbanded. The guild bank's " + amt + " coins went to " + who;
  }
  Object mine = actorU == null ? null : shareBy.get(actorU);
  boolean even = true;
  for (int i = 0; i < rows.size(); i++) if (((Long) ((Object[]) rows.get(i))[2]).longValue() > 0L) even = false;
  return "+" + g.name + " is disbanded. The guild bank's " + amt + " coins went back to " + payees(rows) + " members "
    + (even ? "in equal parts (nobody had put in more than they took out)" : "by contribution")
    + (mine instanceof Long ? " - your share: " + mine + " coins." : ".");
}""")
# 0.1.6 (Skyy 2026-10-01, "some of it but not all. like 30%-40% of what they donated"): a leaving / kicked member's refund before the
# bank cap = floor(pct x net / 100) for a positive net (0 otherwise); pct clamped to 0-100; at most net, so it fits a long
M(gs, r"""
public static long refundFull(long net, long pct) {
  if (net <= 0L || pct <= 0L) return 0L;
  long p = pct > 100L ? 100L : pct;
  return java.math.BigInteger.valueOf(net).multiply(java.math.BigInteger.valueOf(p)).divide(java.math.BigInteger.valueOf(100L)).longValue();
}""")
# {refund (at most the bank), net, refundFull, pct} of member us right now (GCfg.LEAVE_REFUND read once)
M(gs, r"""
public static synchronized long[] refundInfo(@PKG@.Guild g, String us) {
  long pct = (long) @PKG@.GCfg.LEAVE_REFUND;
  if (pct < 0L) pct = 0L;
  if (pct > 100L) pct = 100L;
  long n = netValue(g, us);
  long full = refundFull(n, pct);
  long bank = g.bank < 0L ? 0L : g.bank;
  return new long[] { full > bank ? bank : full, n, full, pct };
}""")
# the refund sentence (ri = refundInfo, refund before the cap ri[2] > 0): you / done pick "You get back" | "You got back X coins to your
# purse" | "Dot gets back" | "Dot got back"; review fix (finding 2): an empty bank (refund 0) says "You get nothing back - the guild bank
# is empty (...)" / "got nothing back - the guild bank was empty"
M(gs, r"""
public static String refundText(String name, boolean you, boolean done, long[] ri) {
  String subj = you ? "You" : name;
  String poss = you ? "your" : "their";
  if (ri[0] <= 0L) return subj + (done ? " got" : (you ? " get" : " gets")) + " nothing back - the guild bank " + (done ? "was" : "is") + " empty (" + ri[3] + "% of " + poss + " contribution of " + num(ri[1]) + " would be " + num(ri[2]) + ").";
  String verb = done ? " got back " : (you ? " get back " : " gets back ");
  String coins = num(ri[0]) + " coins" + (you && done ? " to your purse" : "");
  if (ri[0] < ri[2]) return subj + verb + coins + " - all the guild bank holds (" + ri[3] + "% of " + poss + " contribution of " + num(ri[1]) + " would be " + num(ri[2]) + ").";
  return subj + verb + coins + " (" + ri[3] + "% of " + poss + " contribution of " + num(ri[1]) + ")"
    + (ri[3] < 100L ? "; the rest stays in the bank" + (you && !done ? " for the other members." : ".") : ".");
}""")
# 0.1.6 review (finding 1, Skyy's "some of it but not all"): what is left of a leaving / kicked member's positive contribution after the
# refund goes to the guild - n coins move from member us to the hidden total "~guild" (deposited; never a member: no refund, no disband
# share of its own - a disband splits the whole bank among the members, 0.1.5) and count as the member's withdrawal, so their net ends
# at 0 and a rejoin starts from 0 (leave + rejoin loops get the refund ONCE). Every net still adds up to the bank. n < 0 undoes a move (a
# refused refund); a "~guild" total back at 0|0 is dropped (propsOf never writes one either).
M(gs, r"""
public static synchronized void toGuildNet(@PKG@.Guild g, String us, long n) {
  if (g == null || us == null || n == 0L) return;
  netAdd(g, us, 0L, n);
  netAdd(g, "~guild", n, 0L);
  long[] v = netOf(g, "~guild");
  if (v != null && v[0] == 0L && v[1] == 0L) g.net.remove("~guild");
}""")
# pays the refund ri[0] (ri = refundInfo) of the bank to member m (action leave-refund | kick-refund), 0.1.4's withdraw pattern: SkyyCoins
# loaded and the purse readable first; the lower bank, the raised withdrawn total and (review finding 1) the rest of a positive
# contribution moved to the guild (toGuildNet, pct > 0 only: 0% keeps 0.1.5's totals) are WRITTEN (m still a member) before coins:fn:add
# (offline: SkyyCoins pays their active profile); a failed write / add puts all three back (written again). (finding 5) an info line
# names the payment between the write and coins:fn:add, so a crash in that window can be paid by hand. No refund (0 coins): only the
# rest moves to the guild, in memory - the caller's removeMember write saves it. null = done and logged (guild file log + banklog.log),
# else the reason nothing moved.
M(gs, r"""
public static synchronized String payRefund(@PKG@.Guild g, @PKG@.GMember m, long[] ri, String action) {
  long x = ri[0];
  long rest = (ri[3] > 0L && ri[1] > x) ? ri[1] - x : 0L;
  if (x <= 0L) {
    toGuildNet(g, m.uuid, rest);
    if (rest > 0L) info(m.name + " (" + m.uuid + ") leaves " + g.id + " '" + g.name + "' with no refund (" + action + " 0): their contribution of " + rest + " coins stays with the guild");
    return null;
  }
  if (!coinsReady()) return "SkyyCoins is not loaded";
  if (coinsGet(m.uid) == null) return "the purse cannot be read right now";
  if (x > g.bank) return "the guild bank holds only " + num(g.bank) + " coins";
  g.bank = g.bank - x;
  netAdd(g, m.uuid, 0L, x);
  toGuildNet(g, m.uuid, rest);
  if (!saveGuild(g)) {
    g.bank = g.bank + x;
    netAdd(g, m.uuid, 0L, -x);
    toGuildNet(g, m.uuid, -rest);
    return "the guild file could not be written";
  }
  info(action + " of " + x + " coins for " + m.name + " (" + m.uuid + ") from " + g.id + " '" + g.name + "': the guild file is written (bank " + g.bank + "), paying the purse now");
  if (!coinsAdd(m.uid, x)) {
    g.bank = g.bank + x;
    netAdd(g, m.uuid, 0L, -x);
    toGuildNet(g, m.uuid, -rest);
    saveGuild(g);
    warn(action + " of " + x + " for " + m.name + " (" + m.uuid + ") from " + g.id + " refused by SkyyCoins - bank restored to " + g.bank);
    return "SkyyCoins could not put the coins in the purse";
  }
  addLog(g, m.name, action, x);
  if (rest > 0L) info(m.name + " (" + m.uuid + ") got " + x + " coins back from " + g.id + "; the other " + rest + " coins of their contribution stay with the guild");
  return null;
}""")
