# 0.1.6 review (finding 2): the refund a leave confirm showed, kept with the confirms as CONFIRM "lq:<uuid>:<coins>" -> expiry (15 s = the
# 10 s confirm window + slack; GuildTick's prune drops it with the confirms). quoteOk(us, x): true when there is no live quote for us or
# it is x - every quote of us is consumed either way. quoteLeave replaces the player's quote.
M(gs, r"""
public static boolean quoteOk(String us, long x) {
  long now = System.currentTimeMillis();
  String pre = "lq:" + us + ":";
  boolean any = false;
  boolean hit = false;
  java.util.Iterator it = CONFIRM.entrySet().iterator();
  while (it.hasNext()) {
    java.util.Map.Entry e = (java.util.Map.Entry) it.next();
    String k = String.valueOf(e.getKey());
    if (!k.startsWith(pre)) continue;
    Object v = e.getValue();
    if (v instanceof Long && ((Long) v).longValue() >= now) {
      any = true;
      if (k.equals(pre + x)) hit = true;
    }
    it.remove();
  }
  return !any || hit;
}""")
M(gs, r"""
public static void quoteLeave(String us, long x) {
  quoteOk(us, x);
  CONFIRM.put("lq:" + us + ":" + x, Long.valueOf(System.currentTimeMillis() + 15000L));
}""")
