M(gs, r"""
public static synchronized String requote(@PKG@.Guild g, @PKG@.GMember me, long x, boolean page) {
  if (quoteOk(me.uuid, x)) return null;
  quoteLeave(me.uuid, x);
  if (!page) CONFIRM.put("leave:" + me.uuid, Long.valueOf(System.currentTimeMillis() + 10000L));
  String n = leaveNote(g, me);
  return "=The guild bank changed:" + (n.length() > 0 ? n : " you get nothing back now.") + " " + (page ? "Click Leave" : "Type /guild leave") + " again within 10 s to leave.";
}""")
