M(page, r"""
public void build(@REF@ ref, @UCB@ b, @UEB@ ev, @ST@ st) {
  java.util.UUID u = this.playerRef.getUuid();
  if (this.confirmUntil < System.currentTimeMillis()) this.confirm = "";
  Object[] s = null;
  try { s = @PKG@.GuildStore.snapshot(u); } catch (Throwable t) { @PKG@.GuildStore.warn("guild page snapshot failed: " + t); }
  if (s == null) { this.view = 0; buildNone(b, ev, u); }
  else if (this.view == 1) buildLog(b, ev, u, s);
  else buildGuild(b, ev, u, s);
}""")
M(page, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  try {
    if (data == null) return;
    String a = jsonStr(data, "a");
    if (a.length() == 0) return;
    java.util.UUID u = this.playerRef.getUuid();
    String un = this.playerRef.getUsername();
    long now = System.currentTimeMillis();
    if (this.confirmUntil < now) this.confirm = "";
    if (a.equals("refresh")) { this.info = ""; this.confirm = ""; rebuild(); return; }
    if (a.equals("prev")) { this.pageNo--; this.confirm = ""; rebuild(); return; }
    if (a.equals("next")) { this.pageNo++; this.confirm = ""; rebuild(); return; }
    if (a.equals("expand")) { this.view = 1; this.logPage = 0; this.info = ""; this.confirm = ""; rebuild(); return; }
    if (a.equals("back")) { this.view = 0; this.info = ""; this.confirm = ""; rebuild(); return; }
    if (a.equals("lprev")) { this.logPage--; rebuild(); return; }
    if (a.equals("lnext")) { this.logPage++; rebuild(); return; }
    String res = null;
    String keep = "";
    this.keepInvite = ""; this.keepAmount = ""; this.keepName = ""; this.keepLimit = "";
    String was = this.confirm;
    this.confirm = "";
    if (a.equals("create")) {
      keep = jsonStr(data, "@GName");
      res = @PKG@.GuildStore.create(u, un, keep);
      if (res != null && res.startsWith("-")) this.keepName = keep;
    } else if (a.equals("accept")) {
      res = @PKG@.GuildStore.accept(u, un);
    } else if (a.equals("decline")) {
      res = @PKG@.GuildStore.decline(u, un);
    } else if (a.equals("invite")) {
      keep = jsonStr(data, "@GInvite");
      res = @PKG@.GuildStore.invite(u, un, keep);
      if (res != null && res.startsWith("-")) this.keepInvite = keep;
    } else if (a.equals("deposit") || a.equals("withdraw")) {
      keep = jsonStr(data, "@GAmount");
      res = a.equals("deposit") ? @PKG@.GuildStore.deposit(u, un, keep) : @PKG@.GuildStore.withdraw(u, un, keep);
      if (res != null && res.startsWith("-")) this.keepAmount = keep;
    } else if (a.equals("amount")) {
      keep = jsonStr(data, "@GAmount").trim();
      if (keep.length() > 16) keep = keep.substring(0, 16);
      this.keepAmount = keep;
      boolean wd = @PKG@.GuildStore.canWithdraw(u);
      if (keep.length() == 0) res = "=Type an amount (500, 2k, 1.5m or all), then click Deposit" + (wd ? " or Withdraw." : ".");
      else res = "=Click Deposit" + (wd ? " or Withdraw" : "") + " to move " + keep + " coins. Enter alone never moves coins.";
    } else if (a.equals("limadmin") || a.equals("limmember")) {
      keep = jsonStr(data, "@GLimit").trim();
      res = @PKG@.GuildStore.setLimit(u, un, a.equals("limadmin") ? "admin" : "member", keep);
      if (res != null && res.startsWith("-")) this.keepLimit = keep;
    } else if (a.equals("limit")) {
      keep = jsonStr(data, "@GLimit").trim();
      if (keep.length() > 16) keep = keep.substring(0, 16);
      this.keepLimit = keep;
      if (keep.length() == 0) res = "=Type a daily limit (5k, 0 = no withdrawing, none = no limit), then click Set Admin limit or Set Member limit.";
      else res = "=Click Set Admin limit or Set Member limit to use " + keep + ". Enter alone never changes a limit.";
    } else if (a.equals("leave")) {
      if (was.equals("leave")) { res = @PKG@.GuildStore.leave(u, un, true); if (res != null && res.startsWith("=")) { this.confirm = "leave"; this.confirmUntil = now + 10000L; } }
      else { res = @PKG@.GuildStore.leaveWarning(u); if (res.startsWith("=")) { this.confirm = "leave"; this.confirmUntil = now + 10000L; } }
    } else if (a.equals("disband")) {
      if (was.equals("disband")) res = @PKG@.GuildStore.disband(u, un, true);
      else { res = @PKG@.GuildStore.disbandWarning(u); if (res.startsWith("=")) { this.confirm = "disband"; this.confirmUntil = now + 10000L; } }
    } else {
      int c = a.indexOf(':');
      if (c <= 0 || this.rowIds == null) return;
      String act = a.substring(0, c);
      int idx = -1;
      try { idx = Integer.parseInt(a.substring(c + 1)); } catch (Throwable t) { idx = -1; }
      if (idx < 0 || idx >= this.rowIds.size()) return;
      String tu = (String) this.rowIds.get(idx);
      if (act.equals("promote")) res = @PKG@.GuildStore.promote(u, un, tu);
      else if (act.equals("demote")) res = @PKG@.GuildStore.demote(u, un, tu);
      else if (act.equals("kick")) {
        if (was.equals("kick:" + tu)) res = @PKG@.GuildStore.kick(u, un, tu);
        else { this.confirm = "kick:" + tu; this.confirmUntil = now + 10000L; res = "=Click Sure? within 10 s to remove " + @PKG@.GuildStore.nameOfMember(u, tu) + " from the guild." + @PKG@.GuildStore.kickNote(u, tu); }
      } else if (act.equals("lead")) {
        if (was.equals("lead:" + tu)) res = @PKG@.GuildStore.transfer(u, un, tu, true);
        else { this.confirm = "lead:" + tu; this.confirmUntil = now + 10000L; res = "=Click Confirm? within 10 s to make " + @PKG@.GuildStore.nameOfMember(u, tu) + " the Leader (you become an Admin)."; }
      } else return;
    }
    this.info = res == null ? "+Done." : res;
    rebuild();
  } catch (Throwable t) { @PKG@.GuildStore.warn("guild page click failed: " + t); }
}""")

# ================= GHooks (0.1.2): config kit check hooks + the /guildadmin config | set | reload helpers =================
# SKILL_NAMES (the names SkyySkills 0.4.4 answers in skill:fn:xp and the storage slot each one reads; 0.1.3 adds Fury / Berserker /
# Combat.Berserker = 14 and Divinity / Priest / Combat.Priest = 15) is defined with the GCfg fields since 0.1.3, so GCfg.parseSkills and
# GHooks.slotOf / checkSkills read the same table. A name that is not listed only ASKS first, it is never refused.
F(hk, "public static final String[] SK_NAMES = new String[] { %s };" % ", ".join('"%s"' % n for n, _ in SKILL_NAMES))
F(hk, "public static final int[] SK_SLOTS = new int[] { %s };" % ", ".join(str(s) for _, s in SKILL_NAMES))
M(hk, r"""
public static int slotOf(String lower) {
  for (int i = 0; i < SK_NAMES.length; i++) if (SK_NAMES[i].equals(lower)) return SK_SLOTS[i];
  return -1;
}""")
# the listed names SkyySkills does not know, comma-joined ("" = all known)
M(hk, r"""
public static String unknownOf(String value) {
  if (value == null) return "";
  String[] a = value.split(",");
  StringBuilder u = new StringBuilder();
  for (int i = 0; i < a.length; i++) {
    String x = a[i].trim();
    if (x.length() == 0 || x.equalsIgnoreCase("combat")) continue;
    if (slotOf(x.toLowerCase()) < 0) { if (u.length() > 0) u.append(", "); u.append(x); }
  }
  return u.toString();
}""")
# check=GHooks.checkSkills (xpSkills): null = fine, text = refused, "?text" = ask first (tools/CONFIG-CONTRACT.md binding options)
M(hk, r"""
public static String checkSkills(String key, String value) {
  if (value == null) return null;
  String[] a = value.split(",");
  java.util.HashSet seen = new java.util.HashSet();
  java.util.HashMap slots = new java.util.HashMap();
  int n = 0;
  for (int i = 0; i < a.length; i++) {
    String x = a[i].trim();
    if (x.length() == 0) continue;
    n++;
    if (x.length() > 40) return "A skill name is at most 40 characters: " + x.substring(0, 40) + "...";
    for (int k = 0; k < x.length(); k++) {
      char c = x.charAt(k);
      if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ' ' || c == '.' || c == '_' || c == '-'))
        return "Skill names use letters (and spaces or dots), separated by commas: " + x;
    }
    String lx = x.toLowerCase();
    if (lx.equals("combat")) return "Leave Combat out: it is each member's class skill (Archery, Swordsmanship ...), so it would count twice.";
    if (!seen.add(lx)) return x + " is listed twice.";
    int s = slotOf(lx);
    if (s >= 0) {
      Object o = slots.get(Integer.valueOf(s));
      if (o != null) return x + " and " + o + " are the same skill - list it once.";
      slots.put(Integer.valueOf(s), x);
    }
  }
  if (n == 0) return "List at least one skill, for example Mining,Foraging,Farming.";
  String u = unknownOf(value);
  if (u.length() > 0) return "?" + u + (u.indexOf(',') >= 0 ? " are not SkyySkills skill names" : " is not a SkyySkills skill name") + ", so it would add 0 guild XP. Save anyway?";
  return null;
}""")
# check=GHooks.checkPoll (xpPollSeconds): the tick runs every 5 s, so the loader rounds up to a multiple of 5 - a typed value must be one
M(hk, r"""
public static String checkPoll(String key, String value) {
  try {
    long v = Long.parseLong(value.trim());
    if (v % 5L != 0L) return "Must be a multiple of 5 s (5, 10, 15 ... 300): the guild tick runs every 5 s.";
  } catch (Throwable t) { }
  return null;
}""")
# check=GHooks.checkLimit (defaultAdminLimit / defaultMemberLimit): exactly what GCfg.limProp reads - none (also its other no-limit
# words unlimited / nolimit / -1, so a hand-edited file still exports, imports and restores), or plain whole coins up to its 1e15 cap.
# null = fine, as in checkSkills / checkPoll (the kit resolves a reset to the default text first; null only comes from table / action paths)
M(hk, r"""
public static String checkLimit(String key, String value) {
  String msg = "Type none (no limit), 0 (no withdrawing) or whole coins per game day like 5000 (plain digits, not 5k).";
  if (value == null) return null;
  String t = value.trim().toLowerCase();
  if (t.equals("none") || t.equals("unlimited") || t.equals("nolimit") || t.equals("-1")) return null;
  if (t.length() == 0 || t.length() > 16) return msg;
  for (int k = 0; k < t.length(); k++) { char c = t.charAt(k); if (c < '0' || c > '9') return msg; }
  try { if (Long.parseLong(t) > 1000000000000000L) return "At most 1000000000000000 coins per game day (or none)."; }
  catch (Throwable x) { return msg; }
  return null;
}""")
# /guildadmin set|config|reload go through the kit (validated, logged via=command, versioned, written line by line - spec 1.4.3)
M(hk, r"""
public static int keyIndex(String typed) {
  if (typed == null) return -1;
  String t = typed.trim();
  for (int i = 0; i < @PKG@.CfgRows.KEYS.length; i++) if (@PKG@.CfgRows.KEYS[i].equalsIgnoreCase(t)) return i;
  return -1;
}""")
M(hk, r"""
public static String adminSet(java.util.UUID who, String name, String key, String value) {
  if (who == null) return "-Could not tell who sent this command - nothing was changed.";
  int i = keyIndex(key);
  if (i < 0) return "-Unknown setting: " + @PKG@.GuildStore.clean(key) + ". /guildadmin config lists them.";
  String k = @PKG@.CfgRows.KEYS[i];
  String v = value == null ? "" : value.trim();
  if (v.equalsIgnoreCase("default")) v = null;
  Object[] r = null;
  try { r = @PKG@.CfgFn.set(k, v, who, name, "yes", "command"); } catch (Throwable t) { @PKG@.GuildStore.warn("/guildadmin set " + k + " failed: " + t); r = null; }
  if (r == null || r.length < 3) return "-Could not change " + k + " - see the server log.";
  String st = String.valueOf(r[0]);
  String msg = String.valueOf(r[2]);
  if (st.equals("ok") || st.equals("restart")) {
    String note = "";
    if (k.equals("xpSkills") && r[1] != null) {
      String u = unknownOf(String.valueOf(r[1]));
      if (u.length() > 0) note = " Note: " + u + " - not a SkyySkills skill name, it adds 0 guild XP.";
    }
    return (msg.indexOf(" is already ") >= 0 ? "=" : "+") + msg + note;
  }
  return "-" + msg;
}""")
M(hk, r"""
public static String[] configLines() {
  int n = @PKG@.CfgRows.KEYS.length;
  String[] out = new String[n + 2];
  out[0] = "=SkyyGuilds settings (mods/Skyy_SkyyGuilds/config.properties) - key = value (what it is):";
  for (int i = 0; i < n; i++) {
    String v = null;
    try { v = @PKG@.CfgFn.current(i); } catch (Throwable t) { v = null; }
    out[i + 1] = "=  " + @PKG@.CfgRows.KEYS[i] + " = " + @PKG@.CfgRows.disp(i, v) + "  (" + @PKG@.CfgRows.LABELS[i] + ")";
  }
  out[n + 1] = "=/guildadmin set <key> <value> changes one (value default = back to the default). Also: SkyWynn Menu > Server Setup > Guilds.";
  return out;
}""")
M(hk, r"""
public static String adminReload(java.util.UUID who, String name) {
  if (who == null) return "-Could not tell who sent this command - nothing was changed.";
  Object o = null;
  try { o = new @PKG@.CfgFn().apply(new Object[] { "reload", who, name, "command" }); } catch (Throwable t) { o = null; }
  if (!(o instanceof Object[]) || ((Object[]) o).length < 3) return "-config.properties could not be re-read - see the server log.";
  Object[] r = (Object[]) o;
  String msg = String.valueOf(r[2]);
  if ("ok".equals(r[0])) return "+config.properties: " + msg + " /guildadmin config shows every value.";
  return "-config.properties: " + msg;
}""")

# ================= commands =================
EXEC = "protected void execute(@CTX@ ctx, @ST@ store, @REF@ ref, @PR@ pr, @WLD@ world)"
CMDS = []


def cmd(clsname, name, desc, args, body, perm="@ADV@", subs=(), aliases=()):
    """One AbstractPlayerCommand. args = [(field, argName, argDesc, "STRING" | "GREEDY_STRING")], read into a0, a1, ..."""
    c = pool.makeClass(PKG + "." + clsname, pool.get(T["APC"]))
    for (fld, _an, _ad, _ty) in args:
        F(c, "public @RA@ %s;" % fld)
    lines = ['super("%s", "%s");' % (name, desc), perm]
    if aliases:
        lines.append("addAliases(new String[] { %s });" % ", ".join('"%s"' % a for a in aliases))
    for (fld, an, ad, ty) in args:
        lines.append('this.%s = withRequiredArg("%s", "%s", @ATY@.%s);' % (fld, an, ad, ty))
    for s in subs:
        lines.append("addSubCommand(new @PKG@.%s());" % s)
    C(c, "public %s() {\n  %s\n}" % (clsname, "\n  ".join(lines)))
    reads = "".join('    String a%d = String.valueOf(ctx.get(this.%s));\n' % (i, a[0]) for i, a in enumerate(args))
    M(c, EXEC + " {\n  try {\n" + reads + "    " + body + "\n  } catch (Throwable t) {\n"
      "    @PKG@.GuildStore.warn(\"/" + name + " failed: \" + t);\n"
      "    @PKG@.GuildStore.tell(pr, \"-Something went wrong - the server log has the details.\");\n  }\n}")
    CMDS.append(c)
    return c


