man = B.manifest("SkyyGuilds", VERSION, "SkyWynn guilds: create/invite, ranks Leader/Admin/Member, guild chat (/gc), guild bank (SkyyCoins bridge) with per-rank daily withdraw limits per game day and a full bank log, guild XP from members' skill XP (SkyySkills bridge), seasons, /guild page, settings editable in game (Server Setup, /guildadmin config). Per player. Zero dependencies.", PKG + ".SkyyGuildsPlugin")
man["IncludesAssetPack"] = False
B.assemble(jar, man, OUT)
